const apiConfig=window.AGRINETRA_CONFIG||{};
function apiUrl(path){return `${String(apiConfig.API_BASE_URL||'').replace(/\/$/,'')}${path}`}
async function apiRequest(path,options={}){
  const headers={Accept:'application/json',...(options.headers||{})};
  const token=state?.mode==='admin'?(state.adminToken||sessionStorage.getItem('agrinetra_admin_access_token')):(state?.token||sessionStorage.getItem('agrinetra_access_token'));
  if(token)headers.Authorization=`Bearer ${token}`;
  let body=options.body;
  if(body!==undefined&&!(body instanceof FormData)){headers['Content-Type']='application/json';body=JSON.stringify(body)}
  let response;
  try{response=await fetch(apiUrl(path),{...options,headers,body})}
  catch(error){throw new Error('Could not reach the Agri Mitra API. Check API_BASE_URL and backend CORS settings.')}
  let payload={};
  try{payload=await response.json()}catch(error){payload={}}
  if(!response.ok){const detail=payload.detail||payload.message||payload.error;const error=new Error(Array.isArray(detail)?detail.map(item=>item.msg||String(item)).join(', '):detail||`Request failed (${response.status}).`);error.status=response.status;throw error}
  return payload;
}
