function normalizeScanResponse(payload){
  const root=payload||{};
  let data=payload||{};
  for(let depth=0;depth<3;depth++){const nested=data?.data||data?.prediction||data?.result;if(!nested||typeof nested!=='object')break;data=nested}
  const rawLabel=data.disease||data.plant_disease||data.species||data.class_name||data.class_label||data.predicted_class||data.predicted_label||data.detected_class||data.class||data.label||data.prediction_label||(typeof data.prediction==='string'?data.prediction:'')||'';
  let crop=data.crop||data.plant||data.crop_name||'';
  let disease=String(rawLabel||'').trim();
  if(disease.includes('___')){const parts=disease.split('___');if(!crop)crop=parts[0];disease=parts.slice(1).join('___')}
  disease=disease.replace(/[_-]+/g,' ').replace(/\s+/g,' ').trim();
  const rawConfidence=data.confidence??data.probability??data.score??null;
  let confidence=null;
  if(rawConfidence!==null&&rawConfidence!==undefined){const parsed=Number(String(rawConfidence).replace('%',''));if(Number.isFinite(parsed))confidence=parsed>1?parsed/100:parsed}
  const threshold=Number(apiConfig.CONFIDENCE_THRESHOLD);
  const hasThreshold=apiConfig.CONFIDENCE_THRESHOLD!==null&&apiConfig.CONFIDENCE_THRESHOLD!==''&&Number.isFinite(threshold)&&threshold>=0&&threshold<=1;
  const status=String(data.status||'').toLowerCase();
  const isUncertain=['low_confidence','uncertain','rejected'].includes(status)||['low_confidence','uncertain','rejected'].includes(String(root.status||'').toLowerCase());
  const message=data.message||root.message||'';
  const lowConfidence=data.low_confidence===true||root.low_confidence===true||data.is_confident===false||root.is_confident===false||data.confident===false||data.accepted===false||isUncertain||/unable to confidently|unable to identify|low confidence/i.test(`${disease} ${message}`)||(hasThreshold&&confidence!==null&&confidence<threshold);
  const detections=Array.isArray(data.detected_objects)?data.detected_objects:Array.isArray(data.objects)?data.objects:[];
  const humanDetected=data.human_detected===true||root.human_detected===true||data.is_human===true||root.is_human===true||/(human|person|face)/i.test(String(rawLabel||''))||detections.some(item=>/(human|person|face)/i.test(String(item?.class||item?.label||item?.name||item||'')));
  if(!disease&&!lowConfidence&&!humanDetected)throw new Error('The image API response did not include a prediction. Check the response format in README.md.');
  const predictions=data.top_predictions||root.top_predictions||[];
  const topPredictions=Array.isArray(predictions)?predictions.map(item=>({label:String(item.class||item.label||item.species||'Unknown'),confidence:Number(item.confidence)})):[];
  const species=String(data.species||root.species||'').trim();
  const model=data.model||root.model||'Local image classifier';
  const modelVersion=data.model_version||data.version||root.model_version||root.version||'';
  const recommendationValue=data.recommendation||root.recommendation||data.advice||data.treatment||'';
  const recommendation=typeof recommendationValue==='string'?recommendationValue:'';
  const analysis=data.analysis||root.analysis||null;
  const id=data.scan_id||data.id||root.scan_id||root.id||'';
  if(humanDetected)return {id,crop:'Human detected',species:'',disease:'Human detected',confidence,recommendation,message,model,modelVersion,topPredictions,analysis,isConfident:true,humanDetected:true,analysisType:'human'};
  if(lowConfidence)return {id,crop:'Not identified',species:'',disease:'Unable to confidently identify this image.',confidence,recommendation,message,model,modelVersion,topPredictions,analysis,isConfident:false,humanDetected:false,analysisType:'unknown'};
  return {id,crop:String(crop||root.crop||'Not identified'),species,disease:disease||'Unable to confidently identify the result.',confidence,recommendation,model,modelVersion,topPredictions,analysis,isConfident:!lowConfidence,message,humanDetected:false,analysisType:species?'species':'disease'};
}
