document.addEventListener('submit',async e=>{const form=e.target;if(form?.id!=='crop-form'||state.mode!=='farmer'||!state.token)return;e.preventDefault();e.stopImmediatePropagation();const fd=new FormData(form),button=form.querySelector('button[type="submit"]'),cropName=String(fd.get('name')||'').trim();if(button)button.disabled=true;try{let farms=state.farmerFarms||[];if(!farms.length)farms=await services.farms();let farm=farms[0];if(!farm){const areaText=String(fd.get('area')||'');const area=Number.parseFloat(areaText);farm=await services.createFarm({farm_name:String(fd.get('plot')||`${state.user.name.split(' ')[0]}'s Farm`).trim(),location:[state.user.village,state.user.district,state.user.state].filter(Boolean).join(', ')||null,area:Number.isFinite(area)&&area>0?area:null})}const sowing=String(fd.get('sown')||'').trim();const sowingDate=sowing?new Date(`${sowing}T00:00:00`).toISOString():null;const harvestText=String(fd.get('harvest')||'').trim();let harvestDate=null;if(/^\d+\s*days?$/i.test(harvestText)){const base=sowing?new Date(`${sowing}T00:00:00`):new Date();base.setDate(base.getDate()+Number.parseInt(harvestText,10));harvestDate=base.toISOString()}else if(harvestText){const parsed=new Date(`${harvestText}T00:00:00`);if(!Number.isNaN(parsed.getTime()))harvestDate=parsed.toISOString()}await services.createCrop({farm_id:farm.id,crop_name:cropName,variety:String(fd.get('variety')||'').trim()||null,sowing_date:sowingDate,expected_harvest_date:harvestDate});document.querySelector('.modal-backdrop')?.remove();state.page='crops';await loadFarmerRecords({rerender:false});render();toast(`${cropName} saved to your farm records.`)}catch(error){toast(error?.message||'Could not save the crop. Please try again.');if(button)button.disabled=false}},true);
document.addEventListener('submit',async e=>{const form=e.target;if(form?.id!=='admin-contact-form'||state.mode!=='admin')return;e.preventDefault();e.stopImmediatePropagation();const fd=new FormData(form),button=form.querySelector('button[type="submit"]');if(button)button.disabled=true;const contact={kind:fd.get('kind'),name:String(fd.get('name')||'').trim(),organization:String(fd.get('organization')||'').trim()||null,interests:String(fd.get('interests')||'').trim()||null,phone:String(fd.get('phone')||'').trim()||null,email:String(fd.get('email')||'').trim()||null,location:String(fd.get('location')||'').trim()||null,description:String(fd.get('description')||'').trim()||null,is_active:fd.has('is_active')};try{await services.adminCreateContact(contact);document.querySelector('.modal-backdrop')?.remove();toast('Supplier/buyer contact saved and published.');await loadAdminData()}catch(error){const errorBox=form.querySelector('#admin-contact-error');if(errorBox){errorBox.textContent=error?.message||'Could not save contact.';errorBox.hidden=false}if(button)button.disabled=false}},true);
